SELECT *
FROM INSPECT_DETAIL
WHERE INSPECT_CODE = #{inspectCode}
  AND ASSET_ID = #{assetId}
  AND TARGET_STATUS = 1
ORDER BY TARGET_ITEM

SELECT COUNT(*)
FROM (
         SELECT asset_id, asset_desk
         FROM inspect_detail
         WHERE inspect_code = #{inspectCode}
           AND asset_desk = #{assetDesk}
         GROUP BY asset_id, asset_desk
     )

SELECT COUNT(*)
FROM (
         SELECT asset_id
         FROM inspect_detail
         WHERE inspect_code = #{inspectCode}
           AND asset_desk = #{assetDesk}
           AND inspect_state = #{inspectState}
         GROUP BY asset_id
     )

SELECT COUNT(*)
FROM (
         SELECT asset_id
         FROM inspect_detail
         WHERE inspect_code = #{inspectCode}
           AND inspect_state = #{inspectState}
         GROUP BY asset_id
     )
